/bin/zsh -lc "python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
import re, json
s=Path('index.html').read_text()
class Check(HTMLParser):
 def __init__(self):
  super().__init__(); self.ids=[];self.refs=[];self.h1=0;self.scripts=[];self.current=None;self.names=[];self.images=[]
 def handle_starttag(self,tag,attrs):
  d=dict(attrs)
  if 'id' in d:self.ids.append(d['id'])
  if tag=='a' and d.get('href','').startswith('#') and len(d['href'])>1:self.refs.append(d['href'][1:])
  if tag=='h1':self.h1+=1
  if tag=='script':self.current=[]
  if tag=='img':self.images.append(d)
 def handle_data(self,data):
  if self.current is not None:self.current.append(data)
 def handle_endtag(self,tag):
  if tag=='script':self.scripts.append(''.join(self.current));self.current=None
p=Check();p.feed(s)
assert len(p.ids)==len(set(p.ids)), 'Duplicate IDs'
assert all(x in p.ids for x in p.refs), 'Broken fragment links'
assert p.h1==1
assert len(re.findall(r'class=\"project\"',s))==4
assert len(re.findall(r'class=\"post\"',s))==6
assert not re.search(r'<(?:img|image)["'^>]+(?:src|href)=['"\\\"\\']https?://',s)
for i,js in enumerate(p.scripts):Path('/private/tmp/maya-script-'+str(i)+'.js').write_text(js)
article=re.search(r'<div class=\"article-body\">(.*?)</div><aside',s,re.S).group(1)
bio=re.search(r'<div class=\"bio\">(.*?)</div><div class=\"about-details\">',s,re.S).group(1)
def words(x):return len(re.sub('<["'^>]+>'"',' ',x).split())
print(json.dumps({'file_bytes':len(s.encode()),'projects':4,'posts':6,'h1':p.h1,'ids_and_links':'valid','featured_words':words(article),'biography_words':words(bio),'remote_images':False,'scripts':len(p.scripts)},indent=2))
